import { Component, ViewChild } from '@angular/core';
import { timeout } from 'rxjs';

@Component({
    selector: 'app-transaction-start',
    host: { class: 'childRouteFlex' },
    templateUrl: './transaction-start.component.html',
    styleUrls: ['./transaction-start.component.css']
})
export class TransactionStartComponent {
	@ViewChild('buttonCreate') buttonCreate : any;
    showButtonChoseIsIncome = false;
    firstLoad = true;


    constructor(private elRef:ElementRef) {
		console.log(this.buttonCreate);
    }

    CreateTransaction() {
        this.showButtonChoseIsIncome = !this.showButtonChoseIsIncome;
        this.firstLoad = false;
    }

	blendColors(colorA : any, colorB : any, amount : number) {
		const [rA, gA, bA] = colorA.match(/\w\w/g).map((c : any) => parseInt(c, 16));
		const [rB, gB, bB] = colorB.match(/\w\w/g).map((c : any) => parseInt(c, 16));
		const r = Math.round(rA + (rB - rA) * amount).toString(16).padStart(2, '0');
		const g = Math.round(gA + (gB - gA) * amount).toString(16).padStart(2, '0');
		const b = Math.round(bA + (bB - bA) * amount).toString(16).padStart(2, '0');
		return '#' + r + g + b;
	  }
}
